import React from 'react';
import { Link } from 'react-router-dom'; // 1. Імпорт

const Hero = () => (
    <section className="hero">
        <div className="container">
            <div className="hero-content">
                <h2>Discover Great Films</h2>
                <p>Curated selections, beautiful stills, and film details — enjoy the view.</p>
                <div className="cta">
                    {/* 2. Замінюємо кнопку на Link */}
                    <Link to="/catalog">
                        <button style={{ cursor: 'pointer' }}>Explore Films</button>
                    </Link>
                </div>
            </div>
        </div>
    </section>
);

export default Hero;
